import builtins
import numpy as np
from nuka.editor.app import ActionError
run = app.actions.run
def fails(action, text, **args):
    try:
        run(action, **args)
    except ActionError as e:
        assert text in str(e), (action, args, str(e))
    else:
        raise AssertionError((action, args))
def q():
    return np.array([run('sensor.read', index=k)['values'][0] for k in range(2, len(run('sensor.list')))])
def imu():
    return run('sensor.read', index=1)['values'][2]
def color(name):
    run('sensor.read', index=0, path=r'${out}/' + name + '.npy')
    return np.load(r'${out}/' + name + '.npy')
builtins.dr_fails, builtins.dr_q, builtins.dr_imu, builtins.dr_color = fails, q, imu, color
box = run('scene.spawn', kind='box', pose={'pos': [1.2, 0.0, 0.25], 'quat': [1.0, 0.0, 0.0, 0.0]})['focus']
c = run('sensor.add', type='camera', mount='', position=[-1.6, 0.0, 0.5])
i = run('sensor.add', type='imu', mount=box)
assert c['index'] == 0 and i['index'] == 1, (c, i)
for l in run('robot.links')['links']:
    if l['joint']:
        run('sensor.add', type='joint_state', mount=l['path'])
assert len(run('sensor.list')) == 14, run('sensor.list')
